{"type": "file", "encoding": "utf-8", "name": "GameLoader.cs", "path": "Assets/Match3D/Game/Levels/GameLoader.cs", "size": 15709, "sha": "96b246ca3cf77e511e81739379f12e2141a85e90", "content": "﻿using Match3D.Game.Levels;
using Match3D.Utility;
using System;
using System.Collections.Generic;
using System.Linq;
using Match3D.Game.VolumeMatch.Scripts.Data;
using UnityEngine;
using GameEvents;
using Match3D.Game.Bot;
using EndlessMode;

namespace Match3D.Game
{
    public class GameLoader : MonoBehaviour
    {
        public static event Action OnLevelLoaded;

        [SerializeField] private ItemsSpawner _itemsSpawner;
        [SerializeField] private Transform _thrownItemParent;
        [SerializeField] private GameManager _gameManager;
        [SerializeField] private int objectsPerSet = 3;
        [SerializeField] private GameObject _boostersBar;

        [Header("Deck Sets")]
        [SerializeField] private int deckSetsMin = 2;
        [SerializeField] private int deckSetsMax = 4;

        [Space]
        [SerializeField] private CardInfusionUI infusionUI;

        [Header("Endless")]
        [SerializeField] private EndlessModeManager _endlessModeManager;
        [SerializeField] private EndlessObjectsSpawnManager _endlessObjectsSpawnManager;
        [SerializeField] private EndlessModeBar _endlessModeBar;
        [SerializeField] private InfiniteBossModeBar _infiniteBossModeBar;
        [SerializeField] private GameObject _regularBackground;
        [SerializeField] private GameObject _infiniteBackground;

        public static bool HasGlueOnLevel;
        public static bool HasTrampolineOnLevel;
        public static bool HasWinAndCollectOnLevel;

        private void Start()
        {
            AnalyticsManager.Instance.OnLoadingStep("GameSceneStart");

            _boostersBar.SetActive(false);
            _endlessModeBar.gameObject.SetActive(false);
            _infiniteBossModeBar.gameObject.SetActive(false);
            _regularBackground.SetActive(true);
            _infiniteBackground.SetActive(false);

            var levelLoadRequest = GetLevelLoadRequest();
            if (levelLoadRequest != null)
            {
                if (levelLoadRequest.LevelModel.IsEndless)
                {
                    LoadEndlessLevel(levelLoadRequest.LevelModel, levelLoadRequest.LevelDifficulty);
                }
                else if (levelLoadRequest.LevelModel.IsInfiniteBoss)
                {
                    LoadInfiniteBossLevel(levelLoadRequest.LevelModel, levelLoadRequest.LevelDifficulty);
                }
                else
                {
                    LoadLevel(levelLoadRequest.LevelModel, levelLoadRequest.LevelDifficulty);
                }
                Destroy(levelLoadRequest.gameObject);

                if (levelLoadRequest.BotPlayer)
                {
                    var inputHandler = FindFirstObjectByType<InputHandler>();
                    var botGO = inputHandler.SpawnBot();
                    var bot = botGO.GetComponent<CoreGamePlayBot>();
                    bot.PlayWithCPM(levelLoadRequest.BotCPM);
                }
            }
            else
            {
                LoadNextLevel();
            }
        }

        private LevelLoadRequest GetLevelLoadRequest()
        {
            var levelRequest = FindFirstObjectByType<LevelLoadRequest>();
            return levelRequest;
        }

        private void LoadNextLevel()
        {
            var levelModel = LevelManager.Instance.GetCurrentLevel();
            var dynamicDifficulty = DynamicDifficulty.TierManager.GetCurrentDynamicDifficultyTier();
            var retryOffset = DynamicDifficulty.TierManager.GetRetryTierOffset();
            var levelDifficulty = levelModel.GetDynamicDifficulty(dynamicDifficulty);

            // If there is a retry offset this means they were demoted for losing this level
            // too many times.
            if (retryOffset != 0)
            {
                // Make sure we go down a tier for this level
                dynamicDifficulty = levelDifficulty.Difficulty + retryOffset;
                levelDifficulty = levelModel.GetDynamicDifficulty(dynamicDifficulty);
            }

            LoadLevel(levelModel, levelDifficulty);

            if (AnalyticsManager.Instance)
            {
                AnalyticsManager.Instance.StartLevel(LevelManager.Instance.GetCurrentLevelNumber());
            }
        }

        private void LoadLevel(LevelModel levelModel, LevelDifficulty dynamicDifficulty)
        {
            GameEventsManager.SafeSendEvent(new LevelLoading(levelModel, dynamicDifficulty));
#if UNITY_EDITOR
            //LevelManager.Instance.DebugSetLevelOverride(levelModel);
#endif
            // Clone so we don't modify scriptable object
            dynamicDifficulty = dynamicDifficulty.Clone();

            var preWarmTime = dynamicDifficulty.PreWarmTime;
            var levelObjects = dynamicDifficulty.LevelObjects;
            var levelMonsters = dynamicDifficulty.LevelMonsters;

            if (MonsterSpawner.Instance)
            {
                MonsterSpawner.Instance.Init(preWarmTime, levelMonsters);
            }

            List<ObjectData> deckCards;

            List<ObjectData> originalDeckCards;

            deckCards =
                DeckManager.SelectedCards
                .Select(id =>
                    _itemsSpawner.objectsData.data
                    .FirstOrDefault(c => c.card && c.card.cardId == id))
                .ToList();
            originalDeckCards = deckCards.ToList();

            LevelObject[] levelObjectsWithRemovals = ApplyLevelObjectModifications(levelModel, levelObjects, deckCards, originalDeckCards);

            SpawnLevelObjects(levelModel, levelObjectsWithRemovals);

            infusionUI.gameObject.SetActive(false);
            if (DeckManager.SelectedCards.Count > 0)
            {
                infusionUI.gameObject.SetActive(true);
                infusionUI.Init(originalDeckCards.ToArray());
            }
            else
            {
                Destroy(infusionUI.gameObject);
            }

            HasTrampolineOnLevel = ItemsSpawner.preLevelTrampolineSpawnCount > 1;
            _itemsSpawner.SpawnObject(
                _itemsSpawner.objectsData.trampoline,
                ItemsSpawner.preLevelTrampolineSpawnCount,
                _itemsSpawner.transform,
                false,
                true,
                ForcePositionType.Top);
            ItemsSpawner.preLevelTrampolineSpawnCount = 0;

            HasGlueOnLevel = ItemsSpawner.preLevelGlueSpawnCount > 1;
            _itemsSpawner.SpawnObject(
                _itemsSpawner.objectsData.glueBucket,
                ItemsSpawner.preLevelGlueSpawnCount,
                _itemsSpawner.transform,
                false,
                true,
                ForcePositionType.Top);
            ItemsSpawner.preLevelGlueSpawnCount = 0;

            HasWinAndCollectOnLevel = ItemsSpawner.preLevelCollectAndWinSpawnCount > 0;

            var vialData = _itemsSpawner.objectsData.collectAndWinVial;
            var colorIndex = CollectAndWinLocal.GetCurrentColorIndex();
            GameObject overrideVariant = null;
            if (vialData != null && vialData.assetVariants != null && colorIndex >= 0 && colorIndex < vialData.assetVariants.Length)
            {
                overrideVariant = vialData.assetVariants[colorIndex];
            }
            else
            {
                Debug.LogWarning($"[GameLoader] Missing Collect & Win vial variant for index {colorIndex}; falling back to default asset.");
            }

            _itemsSpawner.SpawnObject(
                vialData,
                ItemsSpawner.preLevelCollectAndWinSpawnCount,
                _itemsSpawner.transform,
                false,
                true,
                ForcePositionType.Top,
                overrideVariant);

            ItemsSpawner.preLevelCollectAndWinSpawnCount = 0;

            var bypassObjects =
                levelObjects
                .Where(lo => lo.Bypass > 0)
                .OrderBy(lo => lo.Bypass)
                .Select(lo => lo.ObjectData)
                .ToArray();

            var excludedBypassObjects =
                levelObjects
                .Where(lo => lo.Bypass < 0)
                .Select(lo => lo.ObjectData)
                .ToList();
            excludedBypassObjects.AddRange(deckCards);

            _itemsSpawner.SetBypassObjects(bypassObjects, excludedBypassObjects.ToArray(), levelModel.BypassCount);

            OnLevelLoaded?.Invoke();

            GameEventsManager.SafeSendEvent(new LevelStarted(levelModel, dynamicDifficulty, originalDeckCards));

            levelModel.Tutorial = levelModel.Tutorial != null ? levelModel.Tutorial : TutorialEventManager.Instance.GetTutorialAssetAtLevel();
            if (levelModel.Tutorial != null) TutorialManager.Instance?.Play(levelModel.Tutorial);

            _boostersBar.SetActive(true);
        }

        private void LoadEndlessLevel(LevelModel levelModel, LevelDifficulty dynamicDifficulty)
        {
            GameEventsManager.SafeSendEvent(new LevelLoading(levelModel, dynamicDifficulty));

            // Clone so we don't modify scriptable object
            dynamicDifficulty = dynamicDifficulty.Clone();

            var preWarmTime = dynamicDifficulty.PreWarmTime;
            var levelObjects = dynamicDifficulty.LevelObjects;
            var levelMonsters = dynamicDifficulty.LevelMonsters;

            var totalItems = levelObjects.Sum(lo => lo.Quantity) * objectsPerSet;
            _itemsSpawner.CreateAndShuffleSpawnPoints(levelModel.InLayerShufflePercentage, levelModel.InterLayerShufflePercentage, totalItems);

            _endlessObjectsSpawnManager.Init(levelObjects, levelModel.EndlessSpawnInterval, levelModel.EndlessModePool.ToList());
            _endlessModeManager.Init(levelModel.Name, levelModel.EndlessMonsterInterval, preWarmTime, levelMonsters);

            Destroy(infusionUI.gameObject);

            OnLevelLoaded?.Invoke();

            GameEventsManager.SafeSendEvent(new LevelStarted(levelModel, dynamicDifficulty, new List<ObjectData>()));

            if (AnalyticsManager.Instance)
            {
                AnalyticsManager.Instance.StartLevelEndless();
            }

            levelModel.Tutorial = levelModel.Tutorial != null ? levelModel.Tutorial : TutorialEventManager.Instance.GetTutorialAssetAtLevel();
            if (levelModel.Tutorial != null) TutorialManager.Instance?.Play(levelModel.Tutorial);

            _endlessModeBar.gameObject.SetActive(true);
        }

        private void LoadInfiniteBossLevel(LevelModel levelModel, LevelDifficulty dynamicDifficulty)
        {
            GameEventsManager.SafeSendEvent(new LevelLoading(levelModel, dynamicDifficulty));

            // Clone so we don't modify scriptable object
            dynamicDifficulty = dynamicDifficulty.Clone();

            var preWarmTime = dynamicDifficulty.PreWarmTime;
            var levelObjects = dynamicDifficulty.LevelObjects;
            var levelMonsters = dynamicDifficulty.LevelMonsters;

            var totalItems = levelObjects.Sum(lo => lo.Quantity) * objectsPerSet;
            _itemsSpawner.CreateAndShuffleSpawnPoints(levelModel.InLayerShufflePercentage, levelModel.InterLayerShufflePercentage, totalItems);

            _endlessObjectsSpawnManager.Init(levelObjects, levelModel.EndlessSpawnInterval, levelModel.EndlessModePool.ToList());
            InfiniteBossManager.Instance.Init(levelModel.Name, preWarmTime, levelMonsters);

            Destroy(infusionUI.gameObject);

            OnLevelLoaded?.Invoke();

            GameEventsManager.SafeSendEvent(new LevelStarted(levelModel, dynamicDifficulty, new List<ObjectData>()));

            if (AnalyticsManager.Instance)
            {
                AnalyticsManager.Instance.StartLevelInfiniteBoss();
            }

            if (levelModel.Tutorial != null) TutorialManager.Instance?.Play(levelModel.Tutorial);

            _infiniteBossModeBar.gameObject.SetActive(true);

            _regularBackground.SetActive(false);
            _infiniteBackground.SetActive(true);
        }

        /// <summary>
        /// Spawns all level objects and tutorial level objects
        /// </summary>
        /// <param name="levelModel"></param>
        /// <param name="levelObjectsWithRemovals"></param>
        private void SpawnLevelObjects(LevelModel levelModel, LevelObject[] levelObjectsWithRemovals)
        {
            foreach (var levelObject in levelObjectsWithRemovals)
            {
                var objectSetCount = levelObject.ObjectData.singleClickAction == VolumeMatch.Scripts.Data.SingleClickAction.None ? objectsPerSet : 1;
                _itemsSpawner.SpawnObject(levelObject.ObjectData, levelObject.Quantity * objectSetCount, _itemsSpawner.transform, false, true, levelObject.ForcePositionType);
            }

            if (levelModel.Tutorial != null)
            {
                if (!TutorialManager.CanPlayTutorial(levelModel.Tutorial)) return;
                if (levelModel.Tutorial.ItemsToForce != null)
                {
                    foreach (var item in levelModel.Tutorial.ItemsToForce)
                    {
                        _itemsSpawner.SpawnObject(item.ItemData, item.Quantity, _itemsSpawner.transform, false, true, item.PositionType);
                    }
                }
            }
        }

        private LevelObject[] ApplyLevelObjectModifications(
            LevelModel levelModel,
            LevelObject[] levelObjects,
            List<ObjectData> deckCards,
            List<ObjectData> originalDeckCards)
        {
            var validLevelObjects = levelObjects.Where(lo => lo.ObjectData != null).ToArray();
            var totalItems = validLevelObjects.Sum(lo => lo.Quantity) * objectsPerSet;
            var uniqueItems =
                validLevelObjects
                .Where(lo => lo.Quantity > 0)
                .Select(lo => lo.ObjectData.id)
                .Distinct()
                .Count();
            _itemsSpawner.CreateAndShuffleSpawnPoints(levelModel.InLayerShufflePercentage, levelModel.InterLayerShufflePercentage, totalItems);

            var levelObjectGroups = ObjectsData.CreateGroups(validLevelObjects.Select(lo => lo.ObjectData).ToArray(), false);
            var replace = LevelObjectHelpers.GetItemReplacementCount(uniqueItems);
            int removeCount = LevelObjectHelpers.GetItemRemoveCountOnWinStreak(StatTracker.WinStreak);
            int itemsAdjusted = 0;
            //var levelObjectsWithAdjustments = LevelObjectHelpers.ReplaceWithEquippedObjects(
            //    _itemsSpawner.objectsData.data,
            //    validLevelObjects,
            //    deckCards,
            //    replace,
            //    out itemsAdjusted);
            var levelObjectsWithAdjustments = LevelObjectHelpers.AddEquippedObjects(
                _itemsSpawner.objectsData.data,
                validLevelObjects,
                deckCards,
                3,
                out itemsAdjusted);


            return LevelObjectHelpers.RemoveRandomObjects(
                levelObjectsWithAdjustments,
                removeCount);
        }

        private static List<ColorAttributes> GetAvailableColorsForLevel(LevelObject[] levelObjects)
        {
            return levelObjects
                .Select(levelObject => levelObject.ObjectData.ColorLabels)
                .Where(color => color != ColorAttributes.None)
                .ToList();
        }
